function initSwitchExamples(root) {
  root.querySelectorAll('[data-guideline-switch]:not([disabled])').forEach(control => control.addEventListener('click', () => {
    const checked = control.getAttribute('aria-checked') === 'true';
    const thumb = control.querySelector('span');
    const small = control.classList.contains('w-7');
    control.setAttribute('aria-checked', String(!checked));
    control.classList.toggle('bg-[#2283E2]', !checked);
    control.classList.toggle('bg-gray-300', checked);
    thumb.classList.toggle(small ? 'left-[14px]' : 'left-[22px]', !checked);
    thumb.classList.toggle(small ? 'left-[2px]' : 'left-[3px]', checked);
  }));
}

