  <section class="glass-panel p-6 md:p-10 mb-8"><h2 class="text-2xl font-bold mb-2">${copy.codeTitle}</h2><p class="text-sm text-gray-500 mb-7">${copy.codeIntro}</p><div class="grid md:grid-cols-2 xl:grid-cols-3 gap-4">${sample(copy.sixDigit,`<div data-code-group role="group" aria-label="${copy.codeLabel}" class="flex items-center gap-2">${Array.from({length:6},(_,i)=>`<input data-code-cell inputmode="numeric" autocomplete="${i===0?'one-time-code':'off'}" maxlength="1" aria-label="${zh?`第 ${i+1} 位`:`Digit ${i+1}`}" class="w-9 h-9 shrink-0 rounded-lg border border-gray-300 bg-white text-center text-lg font-semibold outline-none focus:border-[#2283E2] hidc-numeral">`).join('')}</div><p class="mt-2 text-xs text-gray-500" data-code-status>${copy.codeHint}</p>`)}${sample(copy.fourDigit,codeCells(4,{values:['2','8','','']}))}${sample(copy.grouped,codeCells(6,{separator:3,values:['3','6','1','8','','']}))}${sample(copy.masked,codeCells(6,{masked:true}))}${sample(copy.disabled,codeCells(4,{disabled:true,values:['2','8','4','6']}))}${sample(copy.error,`${codeCells(4,{error:true,values:['2','8','4','6']})}<p class="mt-2 text-xs text-red-500">${zh?'验证码错误，请重新输入':'Incorrect code. Try again.'}</p>`)}</div></section>
