    doTitle: 'Do', dontTitle: 'Avoid', doItems: ['Organize by task and usage frequency','Always make the current location clear','Differentiate expansion, selection, and focus'], dontItems: ['Create hierarchies deeper than three levels','Mix navigation with state toggles at one level','Communicate meaning only with icons, abbreviations, or color'],
    apiTitle: 'API', apiIntro: 'Implementation may follow Arco Menu’s controlled state and trigger model while preserving this guideline’s hierarchy, touch, and cross-screen requirements.', name: 'Property', description: 'Description', type: 'Type', defaultValue: 'Default'
